using System;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.IO;using System.Reflection;using System.Windows;using System.Windows.Controls;using BongoChat;using BongoChat.Protocol;
public static class OtherChestTests
{
 static int checks;static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 static void Select(ChatWindow w,string code){foreach(ComboBoxItem item in ((ComboBox)((Grid)w.Content).FindName("Language")).Items)if((string)item.Tag==code){((ComboBox)((Grid)w.Content).FindName("Language")).SelectedItem=item;return;}}
 static void Capture(ChatWindow window,string file){window.UpdateLayout();window.Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(delegate{}));var root=(FrameworkElement)window.Content;var image=new RenderTargetBitmap((int)Math.Ceiling(root.ActualWidth),(int)Math.Ceiling(root.ActualHeight),96,96,PixelFormats.Pbgra32);image.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var stream=File.Create(file))encoder.Save(stream);}
 [STAThread]public static int Main(string[] args){try{
  string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);AppStorage.Root=root;string game=Path.Combine(root,"game"),folder=Path.Combine(game,"BepInEx","BongoChat");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(game,"BongoCat.exe"),"");
  var state=new BridgeState{protocol=1,version=BridgeSetup.RequiredBridgeVersion,ready=true,autoOtherChestSupported=true,autoChestSupported=true,session="session",room="123",utc=DateTime.UtcNow.ToString("o")};var writer=new AutoChestLeaseWriter(true);
  writer.Write(game,state,true,writer.Revision);string other=Path.Combine(folder,"other-chests.json"),own=Path.Combine(folder,"auto-chests.json");var lease=Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(other));
  Check(lease.enabled&&AutoChestPolicy.ValidForOthers(lease,"session","123",DateTime.UtcNow),"other-member permission is fresh and bound to the current game session and room");
  Check(!File.Exists(own)&&!AutoChestPolicy.Valid(lease,"session",DateTime.UtcNow),"others' permission cannot turn on or masquerade as my own chest permission");
  Check(!AutoChestPolicy.ValidForOthers(lease,"session","456",DateTime.UtcNow)&&!AutoChestPolicy.ValidForOthers(lease,"new-session","123",DateTime.UtcNow),"changing room or game invalidates existing other-member permission");
  Check(!AutoChestPolicy.ValidForOthers(lease,"session","123",DateTime.UtcNow.AddSeconds(7)),"other-member permission expires if the companion stops responding");
  var ownWriter=new AutoChestLeaseWriter();ownWriter.Write(game,state,true,ownWriter.Revision);Check(!AutoChestPolicy.ValidForOthers(Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(own)),"session","123",DateTime.UtcNow),"own chest opt-in does not authorize opening for others");
  int previous=writer.Revision;writer.Invalidate();writer.Write(game,state,false,writer.Revision);writer.Write(game,state,true,previous);Check(!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(other)).enabled,"old polls cannot undo a newer other-member off request");
  state.room="";writer.Write(game,state,true,writer.Revision);Check(!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(other)).enabled,"being outside a room never authorizes gifts");state.room="123";
  state.autoOtherChestSupported=false;writer.Write(game,state,true,writer.Revision);Check(!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(other)).enabled,"bridge without the new feature cannot receive enabled gifting permission");state.autoOtherChestSupported=true;
  state.utc=DateTime.UtcNow.AddMinutes(-1).ToString("o");writer.Write(game,state,true,writer.Revision);Check(!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(other)).enabled,"stale heartbeat never authorizes other-member opening");state.utc=DateTime.UtcNow.ToString("o");
  File.WriteAllText(Path.Combine(folder,"state.json"),Journal.Json.Serialize(state));TabletCompatibility.Configure();new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var w=new ChatWindow(false,game,true,"ko");var grid=(Grid)w.Content;var toggle=(CheckBox)grid.FindName("AutoOtherChests");var ownToggle=(CheckBox)grid.FindName("AutoChests");var hint=(TextBlock)grid.FindName("AutoOtherChestHint");var label=(TextBlock)grid.FindName("AutoOtherChestLabel");
  Check(toggle.IsChecked==false&&ownToggle.IsChecked==false,"new other-member toggle and existing own toggle default independently off");Check(hint.Text.Contains("내 포인트")&&toggle.ToolTip.ToString().Contains("상대가"),"point spending and the recipient are explained before opt-in");toggle.IsChecked=true;w.Poll();Check(Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(other)).enabled&&ownToggle.IsChecked==false,"opting into others' chests leaves own chest automation off");Check(File.ReadAllText(Path.Combine(root,"other-chests.txt"))=="true","other-member opt-in is saved separately");
  ownToggle.IsChecked=true;toggle.IsChecked=false;Check(Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(own)).enabled&&!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(other)).enabled,"turning other-member automation off leaves the own option enabled");ownToggle.IsChecked=false;toggle.IsChecked=true;
  Select(w,"en");Check(label.Text=="Auto-open others' chests"&&hint.Text.Contains("my points"),"English offers an independent label and visible own-point notice");Select(w,"ja");Check(label.Text.Contains("他の人")&&hint.Text.Contains("自分のポイント"),"Japanese explains who receives and pays");
  w.Left=-10000;w.Top=-10000;w.WindowStartupLocation=WindowStartupLocation.Manual;w.ShowActivated=false;w.Show();w.Width=420;w.Height=w.MinHeight;
  foreach(string lang in new[]{"en","ko","ja"}){Select(w,lang);w.UpdateLayout();var composer=(TextBox)typeof(ChatWindow).GetField("composer",flags).GetValue(w);var bottom=composer.TranslatePoint(new Point(composer.ActualWidth,composer.ActualHeight),grid);var language=(ComboBox)grid.FindName("Language");Check(bottom.Y<=grid.ActualHeight+1&&bottom.Y>0&&language.TranslatePoint(new Point(),grid).Y<composer.TranslatePoint(new Point(),grid).Y,lang+" minimum window retains both chest options language picker and composer");w.Width=510;w.Height=820;Capture(w,Path.Combine(root,"others-"+lang+".png"));w.Width=420;w.Height=w.MinHeight;}
  w.Close();Check(!Journal.Json.Deserialize<AutoChestLease>(File.ReadAllText(other)).enabled,"closing the companion disables other-member requests");var reopened=new ChatWindow(false,game,true,"ko");Check(((CheckBox)((Grid)reopened.Content).FindName("AutoOtherChests")).IsChecked==true&&((CheckBox)((Grid)reopened.Content).FindName("AutoChests")).IsChecked==false,"saved independent choices survive reopening");reopened.Close();var demo=new ChatWindow(true,null,true,"en");Check(!((CheckBox)((Grid)demo.Content).FindName("AutoOtherChests")).IsEnabled,"preview cannot enable actual other-member gifts");demo.Close();Application.Current.Shutdown();Console.WriteLine("All "+checks+" other chest app checks passed.");return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}